contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address to) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(amount > 0);
        require(to != address(0));
        require(address(this).balance >= amount);

        uint256 initBalance = address(c).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 afterDepositBalance = address(c).balance;

        uint256 toBalanceBefore = to.balance;

        c.migrateTo(to); if (__ESBMC_reverted()) return;

        uint256 toBalanceAfter = to.balance;
        uint256 cBalanceAfter = address(c).balance;

        assert(
            afterDepositBalance == initBalance + amount &&
            cBalanceAfter == 0 &&
            toBalanceAfter == toBalanceBefore + initBalance + amount
        );
    }

    receive() external payable {}
}

